40	// --- Shared regular-file reading ------------------------------------------
41	//
42	// digest, verify-digest and key-id all walk the same pipeline: require a
43	// regular file, open it, then read its complete raw bytes from the start in
44	// fixed-size passes until normal EOF, treating text and binary content
45	// identically. The three only differ in what happens to each chunk, which is
46	// expressed by a ByteSink (see processFileChunks):
47	//   * digest / verify-digest stream the bytes straight into SHA-256, so their
48	//     memory use does not grow with the file;
49	//   * key-id runs a streaming PEM parser over the chunks: the surrounding
50	//     ASCII whitespace and the base64 text are consumed byte by byte without
51	//     being retained, and only the decoded SubjectPublicKeyInfo DER is kept,
52	//     so its memory use tracks the (small) public-key encoding rather than
53	//     the file size.
54	// The error reporting for the access, open and read stages lives here once;
55	// sinks report only their own processing failures.
56	
57	// Size of every read pass for all three commands.
58	constexpr size_t kReadChunkSize = 64 * 1024;
59	
60	// Requires pathArg to name an existing regular file and opens it for raw
61	// binary reads. The two pre-read failure stages stay distinct: a failure to
62	// stat/access the path ("cannot access", covering a missing path) and an
63	// object that is not a regular file, followed by a failure to open it
64	// ("cannot open"). On failure prints a reason containing pathArg to stderr.
65	bool openRegularInput(const char* pathArg, std::ifstream& in) {
66	    namespace fs = std::filesystem;
67	    const fs::path path(pathArg);
68	
69	    std::error_code ec;
70	    if (!fs::is_regular_file(path, ec)) {
71	        if (ec) {
72	            std::cerr << "sealmark: cannot access '" << pathArg << "': "
73	                      << ec.message() << '\n';
74	        } else {
75	            std::cerr << "sealmark: '" << pathArg
76	                      << "' is not a regular file\n";
77	        }
78	        return false;
79	    }
80	
81	    errno = 0;
82	    in.open(path, std::ios::binary);
83	    if (!in) {
84	        const int err = errno;
85	        std::cerr << "sealmark: cannot open '" << pathArg << "': "
86	                  << (err != 0 ? std::strerror(err) : "open failed") << '\n';
87	        return false;
88	    }
89	    return true;
90	}
