92	// Feeds a regular file's complete raw bytes to sink:
93	//   start()             once, immediately after the file is opened;
94	//   consume(data, size) for every non-empty chunk, including a final short
95	//                       one (a zero-length file yields no consume() call);
96	//   finish()            exactly once, only after a read reaching normal EOF.
97	// A false return aborts the operation and the sink is responsible for its own
98	// diagnostic. A final read shorter than the chunk -- including zero bytes on
99	// an empty file -- after a non-failed read is normal EOF; only a failed read
100	// (badbit) after some bytes were delivered is a read error, which is reported
101	// as such and never reaches finish(). Hence a mid-read failure can never
102	// surface as a digest, a match/mismatch result or a key fingerprint.
103	template <typename ByteSink>
104	bool processFileChunks(const char* pathArg, ByteSink& sink) {
105	    std::ifstream in;
106	    if (!openRegularInput(pathArg, in)) {
107	        return false;
108	    }
109	    if (!sink.start()) {
110	        return false;
111	    }
112	
113	    std::vector<char> buffer(kReadChunkSize);
114	    while (true) {
115	        in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
116	        const std::streamsize got = in.gcount();
117	        if (got > 0 &&
118	            !sink.consume(buffer.data(), static_cast<size_t>(got))) {
119	            return false;
120	        }
121	        if (in.bad()) {
122	            // The file was already opened successfully; this is a read-stage
123	            // failure, never an open error or a content/format problem.
124	            std::cerr << "sealmark: failed to read '" << pathArg << "'\n";
125	            return false;
126	        }
127	        if (got < static_cast<std::streamsize>(buffer.size())) {
128	            break;  // normal end of file: a short or empty final read
129	        }
130	    }
131	
132	    return sink.finish();
133	}
