135	// Streams every chunk through SHA-256 with fixed-size buffers, so memory use
136	// stays constant regardless of file size. On a processing failure it prints
137	// the reason (including pathArg) itself; after success hash() holds exactly
138	// kSha256Size bytes.
139	class Sha256StreamSink {
140	public:
141	    explicit Sha256StreamSink(const char* pathArg) : pathArg_(pathArg) {}
142	
143	    bool start() {
144	        ctx_.reset(EVP_MD_CTX_new());
145	        if (!ctx_ ||
146	            EVP_DigestInit_ex(ctx_.get(), EVP_sha256(), nullptr) != 1) {
147	            fail("SHA-256 initialization failed");
148	            return false;
149	        }
150	        return true;
151	    }
152	
153	    bool consume(const char* data, size_t size) {
154	        if (EVP_DigestUpdate(ctx_.get(), data, size) != 1) {
155	            fail("SHA-256 computation failed");
156	            return false;
157	        }
158	        return true;
159	    }
160	
161	    bool finish() {
162	        unsigned int hashLen = 0;
163	        if (EVP_DigestFinal_ex(ctx_.get(), hash_, &hashLen) != 1 ||
164	            hashLen != kSha256Size) {
165	            fail("SHA-256 computation failed");
166	            return false;
167	        }
168	        return true;
169	    }
170	
171	    const unsigned char* hash() const { return hash_; }
172	
173	private:
174	    void fail(const char* what) {
175	        std::cerr << "sealmark: " << what << " for '" << pathArg_ << "'\n";
176	    }
177	
178	    const char* pathArg_;
179	    std::unique_ptr<EVP_MD_CTX, decltype(&EVP_MD_CTX_free)> ctx_{
180	        nullptr, &EVP_MD_CTX_free};
181	    unsigned char hash_[kSha256Size] = {};
182	};
