399	    static int base64Value(unsigned char c) {
400	        if (c >= 'A' && c <= 'Z') return c - 'A';
401	        if (c >= 'a' && c <= 'z') return c - 'a' + 26;
402	        if (c >= '0' && c <= '9') return c - '0' + 52;
403	        if (c == '+') return 62;
404	        if (c == '/') return 63;
405	        return -1;
406	    }
407	
408	    // Feeds one character of a payload line. '-' is deliberately outside the
409	    // alphabet (it starts the END marker, handled by the caller), so any other
410	    // PEM boundary fails here rather than being consumed. Decoding is strict
411	    // and canonical, quantum by quantum; padding is legal only as the
412	    // conventional "x=" / "xx==" tail of the stream, and its unused bits must
413	    // be zero. This mirrors the former whole-file decoder exactly.
414	    bool feedBase64Data(unsigned char c) {
415	        phase_ = Phase::kBodyData;
416	        lineEmpty_ = false;
417	
418	        quantum_[quantumLen_++] = c;
419	        if (quantumLen_ < 4) {
420	            return true;  // wait for the rest of the quantum
421	        }
422	        quantumLen_ = 0;
423	
424	        const int a = base64Value(quantum_[0]);
425	        const int b = base64Value(quantum_[1]);
426	        if (a < 0 || b < 0) {
427	            return false;
428	        }
429	
430	        const bool pad2 = quantum_[2] == '=';
431	        const bool pad3 = quantum_[3] == '=';
432	        if (sawPadding_) {
433	            return false;  // no complete quantum may follow a padded one
434	        }
435	
436	        if (pad2) {
437	            if (!pad3) {
438	                return false;  // '=' at position 2 requires one at position 3
439	            }
440	            if ((b & 0x0f) != 0) {
441	                return false;  // non-canonical: unused padding bits must be 0
442	            }
443	            der_.push_back(static_cast<unsigned char>((a << 2) | (b >> 4)));
444	            sawPadding_ = true;
445	        } else {
446	            const int cv = base64Value(quantum_[2]);
447	            if (cv < 0) {
448	                return false;
449	            }
450	            if (pad3) {
451	                if ((cv & 0x03) != 0) {
452	                    return false;  // non-canonical: unused padding bits must be 0
453	                }
454	                der_.push_back(
455	                    static_cast<unsigned char>((a << 2) | (b >> 4)));
456	                der_.push_back(static_cast<unsigned char>(
457	                    ((b & 0x0f) << 4) | (cv >> 2)));
458	                sawPadding_ = true;
459	            } else {
460	                const int d = base64Value(quantum_[3]);
461	                if (d < 0) {
462	                    return false;
463	                }
464	                der_.push_back(
465	                    static_cast<unsigned char>((a << 2) | (b >> 4)));
466	                der_.push_back(static_cast<unsigned char>(
467	                    ((b & 0x0f) << 4) | (cv >> 2)));
468	                der_.push_back(static_cast<unsigned char>(
469	                    ((cv & 0x03) << 6) | d));
470	            }
471	        }
472	        return true;
473	    }
474	
475	    // At EOF the payload must have ended on a quantum boundary and must
476	    // decode to at least one byte.
477	    bool flushQuantumAtEnd() {
478	        if (quantumLen_ != 0 || der_.empty()) {
479	            return false;
480	        }
481	        return true;
482	    }
483	
484	    // Validates that the decoded payload is one complete SubjectPublicKeyInfo
485	    // DER structure covering every byte, understood by the crypto library, and
486	    // in canonical encoding. Re-encoding the parsed structure must reproduce
487	    // the payload byte for byte; that round trip rules out non-DER BER
488	    // encodings and other representations OpenSSL might otherwise accept. The
489	    // bytes hashed for the fingerprint are therefore the canonical SPKI DER,
490	    // so PEM line wrapping and line endings never influence the result.
491	    bool validateSpkiDer() {
492	        const unsigned char* p = der_.data();
493	        const std::unique_ptr<EVP_PKEY, decltype(&EVP_PKEY_free)> pkey(
494	            d2i_PUBKEY_ex(nullptr, &p, static_cast<long>(der_.size()), nullptr,
495	                          nullptr),
496	            &EVP_PKEY_free);
497	        if (!pkey) {
498	            return false;
499	        }
500	        if (p - der_.data() != static_cast<ptrdiff_t>(der_.size())) {
501	            return false;  // trailing bytes after the SPKI structure
502	        }
503	
504	        const int encLen = i2d_PUBKEY(pkey.get(), nullptr);
505	        if (encLen <= 0 || static_cast<size_t>(encLen) != der_.size()) {
506	            return false;
507	        }
508	        std::vector<unsigned char> reencoded(static_cast<size_t>(encLen));
509	        unsigned char* q = reencoded.data();
510	        if (i2d_PUBKEY(pkey.get(), &q) != encLen || reencoded != der_) {
511	            return false;  // non-canonical DER
512	        }
513	        return true;
514	    }
515	
516	    void reportInvalid() const {
517	        std::cerr << "sealmark: '" << pathArg_
518	                  << "' does not contain a single valid PEM-encoded "
519	                     "SubjectPublicKeyInfo public key (PUBLIC KEY)\n";
520	    }
521	
522	    Phase phase_ = Phase::kPreamble;
523	    size_t markerMatched_ = 0;  // prefix length of the marker being matched
524	    bool lineEmpty_ = true;     // current body line has seen no data yet
525	    unsigned char quantum_[4] = {};
526	    size_t quantumLen_ = 0;
527	    bool sawPadding_ = false;  // a padded (final) quantum already occurred
528	    bool failed_ = false;
529	    const char* pathArg_ = nullptr;
530	    std::vector<unsigned char> der_;
531	};
